import socket, concurrent.futures
hosts=['172.20.0.3','172.20.0.4']
def chk(a):
    h,p=a
    s=socket.socket(); s.settimeout(0.8)
    try:
        s.connect((h,p)); return (h,p)
    except Exception: return None
    finally: s.close()
tasks=[(h,p) for h in hosts for p in range(1,10001)]
res=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=400) as ex:
    for r in ex.map(chk,tasks):
        if r: res.append(r)
