&lt;?php
session_start();
define('IN_OA', true);
require_once __DIR__ . '/common/db.php';

$error = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = isset($_POST['username']) ? trim($_POST['username']) : '';
    $password = isset($_POST['password']) ? trim($_POST['password']) : '';

    $stmt = $conn-&gt;prepare(&quot;SELECT id, username, realname, department, role FROM oa_users WHERE username = ? AND password = MD5(?) AND status = 1&quot;);
    $stmt-&gt;bind_param(&quot;ss&quot;, $username, $password);
    $stmt-&gt;execute();
    $result = $stmt-&gt;get_result();

    if ($result-&gt;num_rows &gt; 0) {
        $user = $result-&gt;fetch_assoc();
        $_SESSION['oa_logged_in'] = true;
        $_SESSION['oa_user_id'] = $user['id'];
        $_SESSION['oa_username'] = $user['username'];
        $_SESSION['oa_realname'] = $user['realname'];
        $_SESSION['oa_department'] = $user['department'];
        $_SESSION['oa_role'] = $user['role'];
        header('Location: /dashboard.php');
        exit;
    } else {
        $error = '用户名或密码错误';
    }
}
