<?php
/**
 * 内部运维代理工具（仅限内网使用）
 * 管理员用于从外网快速访问内网服务
 * 
 * 用法：
 *   GET  /proxy.php?url=http://192.168.10.20/login.php
 *   POST /proxy.php?url=http://192.168.10.20/login.php  (表单数据自动转发)
 */

// 简单鉴权：需要登录后台（复用 admin session）
session_start();
if (!isset($_SESSION['admin_logged_in']) || $_SESSION['admin_logged_in'] !== true) {

}

$target_url = isset($_GET['url']) ? $_GET['url'] : '';

if (empty($target_url)) {
    header('Content-Type: text/html; charset=utf-8');
    echo '<h2>内网代理工具</h2>';
    echo '<p>用法: proxy.php?url=http://目标地址</p>';
    echo '<form method="get"><input name="url" placeholder="http://192.168.10.20/" style="width:400px;padding:8px;"><button style="padding:8px 16px;">访问</button></form>';
    exit;
}

// 初始化 curl
$ch = curl_init();

// 基础设置
curl_setopt($ch, CURLOPT_URL, $target_url);
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
curl_setopt($ch, CURLOPT_FOLLOWLOCATION, true);
curl_setopt($ch, CURLOPT_MAXREDIRS, 5);
curl_setopt($ch, CURLOPT_TIMEOUT, 30);
curl_setopt($ch, CURLOPT_HEADER, false);
curl_setopt($ch, CURLOPT_SSL_VERIFYPEER, false);

// 转发 Cookie（维持目标站 session）
$cookie_file = '/tmp/proxy_cookies_' . md5(session_id() ?: 'default') . '.txt';
curl_setopt($ch, CURLOPT_COOKIEJAR, $cookie_file);
curl_setopt($ch, CURLOPT_COOKIEFILE, $cookie_file);

// 如果是 POST 请求，转发 POST 数据
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($_POST));
    curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: application/x-www-form-urlencoded']);
}

// 执行请求
$response = curl_exec($ch);
$http_code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
$content_type = curl_getinfo($ch, CURLINFO_CONTENT_TYPE);

if (curl_errno($ch)) {
    header('Content-Type: text/html; charset=utf-8');
    echo '<h2>代理请求失败</h2>';
    echo '<p>错误: ' . htmlspecialchars(curl_error($ch)) . '</p>';
    echo '<p><a href="javascript:history.back()">返回</a></p>';
} else {
    // 设置响应头
    if ($content_type) {
        header('Content-Type: ' . $content_type);
    }

    // 重写页面中的链接，让后续请求也走代理
    $parsed = parse_url($target_url);
    $base_url = $parsed['scheme'] . '://' . $parsed['host'];
    if (isset($parsed['port'])) {
        $base_url .= ':' . $parsed['port'];
    }

    // 简单的 URL 重写（让页面内的链接继续走代理）
    $response = preg_replace(
        '/\b(action|href|src)=["\'](?!http|\/\/|#|javascript)([^"\']*)["\']/',
        '$1="/proxy.php?url=' . urlencode($base_url) . '/$2"',
        $response
    );

    echo $response;
}

curl_close($ch);
